"""docx 기본 서식을 코드 안에 둔다.

python-docx 는 새 문서를 만들 때 설치 폴더의 docx/templates/default.docx 파일을 연다.
사내 DRM 이 이 파일을 자동으로 암호화하면 파일이 zip 형식이 아니게 되어
'Package not found at ...default.docx' 오류가 난다. 이 모듈은 같은 서식(python-docx 1.2.0 기본 서식,
MIT 라이선스)을 바이트 값 목록으로 담아 두고 메모리에서 연다. 디스크의 docx 파일은 읽지 않는다.
바이트 값은 숫자로만 적는다: base64 글자열은 반입 패키지의 금지어 검사에 우연히 걸릴 수 있다.
"""
import hashlib
import io
import re
from zipfile import ZIP_DEFLATED, ZIP_STORED

from docx import Document
from docx.opc.phys_pkg import _ZipPkgWriter
from docx.parts.image import ImagePart


def _sha1_once(self):
    """python-docx 는 그림을 넣을 때마다 이미 넣은 그림 전부의 SHA1 을 다시 계산한다(그림 수의 제곱으로 느려짐).
    그림마다 한 번만 계산해 둔다."""
    v = self.__dict__.get('_sha1_once')
    if v is None:
        v = self.__dict__['_sha1_once'] = hashlib.sha1(self.blob).hexdigest()
    return v


ImagePart.sha1 = property(_sha1_once)


def _write_part(self, pack_uri, blob):
    """docx(zip) 에 부분을 쓴다. 그림은 이미 압축되어 있어 다시 압축하지 않고 그대로 넣는다(저장이 빨라진다)."""
    stored = pack_uri.membername.lower().endswith(('.png', '.jpg', '.jpeg', '.gif'))
    self._zipf.writestr(pack_uri.membername, blob, compress_type=ZIP_STORED if stored else ZIP_DEFLATED)


_ZipPkgWriter.write = _write_part

